#!/bin/sh
# generated by rack:fleet render from infra/rack-switch-fleet/sites/larch.json
routes=
if ip -4 -o addr show dev mgmt0 2>/dev/null | grep -qF ' 192.168.60.10/'; then
  routes="${routes:+$routes,}192.168.60.14/32,192.168.60.15/32"
fi
if ip -4 -o addr show dev eno1 2>/dev/null | grep -qF ' 192.168.61.1/30'; then
  routes="${routes:+$routes,}192.168.61.2/32"
fi
exec tailscale --socket=/run/tailscale/tailscaled.sock set --advertise-routes="$routes"
